-- The sequence a column owns, as `public.<name>`: a `SERIAL`'s and a `BIGSERIAL`'s, an identity
-- column's (both kinds), one attached by `OWNED BY`, and a column-name spelling taken
-- verbatim (`MixCol`, a keyword column). NULL for a column that owns none — a plain
-- column, and one whose `DEFAULT nextval` only references a sequence it does not own.
-- @setup
CREATE TABLE ss (id serial PRIMARY KEY, b bigserial, i int GENERATED ALWAYS AS IDENTITY, j int GENERATED BY DEFAULT AS IDENTITY, plain int, "MixCol" serial, "select" serial);
CREATE SEQUENCE own_s OWNED BY ss.plain;
CREATE SEQUENCE free_s;
CREATE TABLE dflt (a int DEFAULT nextval('free_s'), z int);
-- @test
SELECT pg_get_serial_sequence('ss', 'id') AS serial, pg_get_serial_sequence('ss', 'b') AS bigserial,
  pg_get_serial_sequence('ss', 'i') AS identity_always, pg_get_serial_sequence('ss', 'j') AS identity_default,
  pg_get_serial_sequence('ss', 'plain') AS owned_by, pg_get_serial_sequence('ss', 'MixCol') AS mixed_case,
  pg_get_serial_sequence('ss', 'select') AS keyword, pg_get_serial_sequence('dflt', 'a') AS referenced,
  pg_get_serial_sequence('dflt', 'z') AS none;
